"""Synthetic Claude Code sessions (group E). ~/.claude/projects/<dir>/<uuid>.jsonl (+ subagents/, tool-results/) and
claude-home/history.jsonl. Sessions run 2026-08-04 (new Mac) -> 2026-10-16. Six headless `sdk-cli` sessions share the same
terse prompt but each contains a real fix (HARD CASE: automated-looking session with real work)."""
import os, sys, json, datetime, hashlib
sys.path.insert(0, os.path.dirname(__file__))
from synthlib import *

# ------------------------------------------------------------------ native-shape helpers
ALNUM = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
LOWER = 'abcdefghijklmnopqrstuvwxyz0123456789'


def tok(seed, n=22, alphabet=ALNUM):
    h = hashlib.sha256(str(seed).encode()).digest()
    while len(h) < n: h += hashlib.sha256(h).digest()
    return ''.join(alphabet[b % len(alphabet)] for b in h[:n])


def zts(d):
    d = d.astimezone(UTC)
    return d.strftime('%Y-%m-%dT%H:%M:%S.') + f'{d.microsecond // 1000:03d}Z'


def numbered(text, start=1):
    return '\n'.join(f'{i}\t{l}' for i, l in enumerate(text.split('\n'), start))


def cc_version(d):
    days = (dt(d).date() - datetime.date(2026, 8, 4)).days
    return f'2.1.{214 + int(days * 87 / 74)}'


def proj_dir(cwd):
    return ''.join(c if c.isalnum() else '-' for c in cwd)


class CCSession:
    def __init__(self, key, cwd, start, branch='main', entry='cli', model='claude-opus-5', title=None, mode='default'):
        self.key = key; self.sid = uid('cc-session-' + key); self.cwd = cwd; self.dir = proj_dir(cwd)
        self.t = dt(start); self.branch = branch; self.entry = entry; self.model = model; self.mode = mode
        self.version = cc_version(start)
        self.recs = []; self.parent = None; self.n = 0; self.prompt_id = None; self.prompts = []
        self.subagents = {}; self.tool_results = {}; self.msg = None
        if title: self.recs.append({'type': 'ai-title', 'aiTitle': title, 'sessionId': self.sid})
        if entry == 'cli':
            self.recs.append({'type': 'file-history-snapshot', 'messageId': uid(key + '/snap'),
                              'snapshot': {'messageId': uid(key + '/snap'), 'trackedFileBackups': {}, 'timestamp': zts(self.t)},
                              'isSnapshotUpdate': False})

    def _id(self, what):
        self.n += 1
        return uid(f'{self.key}/{what}/{self.n}')

    def tick(self, s):
        self.t = self.t + datetime.timedelta(seconds=s, milliseconds=(self.n * 389 + 17) % 1000)
        return self.t

    def _common(self):
        return {'userType': 'external', 'entrypoint': self.entry, 'cwd': self.cwd, 'sessionId': self.sid, 'version': self.version,
                'gitBranch': self.branch}

    def _user(self, content, gap, side=None, agent=None):
        u = self._id('u')
        if not agent: self.msg = None
        r = {'parentUuid': agent.parent if agent else self.parent, 'isSidechain': bool(agent)}
        if agent: r['agentId'] = agent.aid
        r.update({'promptId': self.prompt_id, 'type': 'user', 'message': {'role': 'user', 'content': content}, 'uuid': u,
                  'timestamp': zts(self.tick(gap))})
        if isinstance(content, str):
            r['permissionMode'] = self.mode
            if self.entry == 'sdk-cli': r['promptSource'] = 'sdk'
        r.update(self._common())
        if agent: agent.parent = u
        else: self.parent = u
        (side if side is not None else self.recs).append(r)
        return u

    def _asst(self, block, gap, stop='tool_use', side=None, agent=None, new_msg=True):
        u = self._id('a')
        if new_msg or self.msg is None:
            self.msg = ('msg_01' + tok(f'{self.key}msg{self.n}', 22), 'req_011C' + tok(f'{self.key}req{self.n}', 20))
        mid, rid = self.msg
        r = {'parentUuid': agent.parent if agent else self.parent, 'isSidechain': bool(agent)}
        if agent: r['agentId'] = agent.aid
        r.update({'message': {'model': self.model, 'id': mid, 'type': 'message', 'role': 'assistant', 'content': [block],
                              'stop_reason': stop, 'stop_sequence': None,
                              'usage': {'input_tokens': 3, 'cache_creation_input_tokens': 900 + (self.n * 137) % 4000,
                                        'cache_read_input_tokens': 18000 + self.n * 1210,
                                        'output_tokens': max(12, len(json.dumps(block)) // 4), 'service_tier': 'standard'}},
                  'requestId': rid, 'type': 'assistant', 'uuid': u, 'timestamp': zts(self.tick(gap))})
        r.update(self._common())
        if agent: agent.parent = u
        else: self.parent = u
        (side if side is not None else self.recs).append(r)
        return u

    # ---- steps
    def user(self, text, paste=None, gap=40):
        self.prompt_id = uid(f'{self.key}/prompt/{len(self.prompts)}')
        self._user(text + ('\n\n' + paste if paste else ''), gap)
        self.prompts.append((self.t, text, paste))

    def say(self, text, gap=12, final=False):
        self._asst({'type': 'text', 'text': text}, gap, stop='end_turn' if final else 'tool_use', new_msg=self.msg is None)

    def tool(self, name, inp, result, gap=6, run=3, error=False, persist=False, agent=None, side=None):
        tid = 'toolu_01' + tok(f'{self.key}tool{self.n}{name}', 22)
        self._asst({'type': 'tool_use', 'id': tid, 'name': name, 'input': inp}, gap, side=side, agent=agent,
                   new_msg=agent is not None or self.msg is None)
        content = result
        if persist:
            rid = 'b' + tok(f'{self.key}persist{self.n}', 8, LOWER)
            self.tool_results[rid] = result
            path = f'/Users/divadbaroon/.claude/projects/{self.dir}/{self.sid}/tool-results/{rid}.txt'
            content = (f'<persisted-output>\nOutput too large ({len(result.encode()) / 1024:.1f}KB). Full output saved to: {path}\n\n'
                       f'Preview (first 2KB):\n{result[:2000]}\n</persisted-output>')
        res = {'tool_use_id': tid, 'type': 'tool_result', 'content': content}
        if error: res['is_error'] = True
        self._user([res], run, side=side, agent=agent)
        return tid

    def read(self, path, text, **kw):
        return self.tool('Read', {'file_path': path}, numbered(text), **kw)

    def bash(self, command, output, description='', **kw):
        inp = {'command': command}
        if description: inp['description'] = description
        return self.tool('Bash', inp, output, **kw)

    def edit(self, path, old, new, **kw):
        return self.tool('Edit', {'file_path': path, 'old_string': old, 'new_string': new},
                         f'The file {path} has been updated successfully.', **kw)

    def write(self, path, content, **kw):
        return self.tool('Write', {'file_path': path, 'content': content}, f'File created successfully at: {path}', **kw)

    def grep(self, pattern, path, output, **kw):
        return self.tool('Grep', {'pattern': pattern, 'path': path, 'output_mode': 'content', '-n': True}, output, **kw)

    def agent(self, agent_type, description, prompt, steps, result, gap=8):
        aid = 'a' + tok(f'{self.key}agent{self.n}', 16, '0123456789abcdef')
        tid = 'toolu_01' + tok(f'{self.key}agenttool{self.n}', 22)
        self._asst({'type': 'tool_use', 'id': tid, 'name': 'Agent',
                    'input': {'description': description, 'prompt': prompt, 'subagent_type': agent_type}}, gap, new_msg=self.msg is None)
        side = []

        class _A: pass
        ag = _A(); ag.aid = aid; ag.parent = None
        self._user(prompt, 1, side=side, agent=ag)
        for name, inp, out in steps:
            self.tool(name, inp, out, gap=5, run=2, agent=ag, side=side)
        self._asst({'type': 'text', 'text': result}, 9, stop='end_turn', side=side, agent=ag)
        self.subagents[aid] = (side, {'agentType': agent_type, 'description': description, 'toolUseId': tid, 'spawnDepth': 1})
        self._user([{'tool_use_id': tid, 'type': 'tool_result', 'content': [{'type': 'text', 'text': result}]}], 2)
        return aid

    def save(self, g, *, project_ids, notes=''):
        if self.prompts:
            self.recs.append({'type': 'last-prompt', 'lastPrompt': self.prompts[-1][1][:120], 'leafUuid': self.parent, 'sessionId': self.sid})
        times = [dt(r['timestamp']) for r in self.recs if 'timestamp' in r]
        t0, t1 = min(times), max(times)
        assert t1 <= REF, (self.key, t1)
        rel = f'projects/{self.dir}/{self.sid}.jsonl'
        acct = 'Claude Code CLI (~/.claude/projects)'
        g.jsonl(rel, self.recs, t0, t1, account=acct, project_ids=project_ids, notes=notes,
                modeled_on='authentic/claude-code/projects/<dir>/<session>.jsonl record shape', source=f'~/.claude/projects/{self.dir}/{self.sid}.jsonl')
        for aid, (recs, meta) in self.subagents.items():
            st = [dt(r['timestamp']) for r in recs]
            base = f'projects/{self.dir}/{self.sid}/subagents/agent-{aid}'
            g.text(base + '.jsonl', ''.join(json.dumps(r, separators=(',', ':'), ensure_ascii=False) + '\n' for r in recs), min(st), max(st),
                   account=acct, project_ids=project_ids, label_key=rel, modeled_on='authentic/claude-code subagents/agent-<id>.jsonl shape')
            g.json(base + '.meta.json', meta, min(st), min(st), indent=None, account=acct, project_ids=project_ids, label_key=rel,
                   modeled_on='authentic/claude-code subagents/agent-<id>.meta.json shape')
        for rid, txt in self.tool_results.items():
            g.text(f'projects/{self.dir}/{self.sid}/tool-results/{rid}.txt', txt, t0, t1, account=acct, project_ids=project_ids,
                   label_key=rel, modeled_on='authentic/claude-code tool-results/<id>.txt')
        SESSIONS.append((self, project_ids))
        return rel


