s.user("experiment time. i have 12 long transcripts in experiments/transcripts/ where i hand-tagged the decisions that mattered (lines with `DECISION:` in my notes file, decisions.yaml). i want to know how many of those decisions survive (a) claude code's built-in auto compaction summary vs (b) an hc note where i marked segments. the summaries are already saved as experiments/auto/<id>.md and experiments/hc/<id>.md. write the scoring script: for each decision, ask whether it's recoverable from the summary. use simple keyword matching first, we can do an llm judge later")
s.bash('ls experiments/ experiments/transcripts | head; head -20 experiments/decisions.yaml', "experiments/:\nauto\ndecisions.yaml\nhc\ntranscripts\n\nexperiments/transcripts:\nt01.jsonl\nt02.jsonl\nt03.jsonl\nt04.jsonl\nt05.jsonl\nt06.jsonl\nt07.jsonl\nt08.jsonl\nt09.jsonl\n\nt01:\n  - id: t01-d1\n    text: use pnpm not npm in the canvas repo\n    keys: [pnpm]\n  - id: t01-d2\n    text: card ids are ulids, never array indexes\n    keys: [ulid]\n  - id: t01-d3\n    text: do not touch electron main process files\n    keys: [electron, main process]\nt02:\n  - id: t02-d1\n    text: dates in exports are UTC with Z suffix\n    keys: [utc, Z suffix]", 'Look at experiment layout and decisions file')
s.write(f'{CP}/experiments/score.py', '"""Score how many hand-tagged decisions survive each compaction summary (keyword recall)."""\nimport json, re, sys, yaml\nfrom pathlib import Path\n\nE = Path(__file__).parent\nDEC = yaml.safe_load(open(E / "decisions.yaml"))\n\n\ndef recovered(dec, summary):\n    s = summary.lower()\n    return all(re.search(r"\\b" + re.escape(k.lower()) + r"\\b", s) for k in dec["keys"])\n\n\ndef main():\n    rows = []\n    for tid, decs in sorted(DEC.items()):\n        for arm in ("auto", "hc"):\n            p = E / arm / f"{tid}.md"\n            if not p.exists():\n                continue\n            text = p.read_text()\n            hit = sum(recovered(d, text) for d in decs)\n            rows.append({"t": tid, "arm": arm, "decisions": len(decs), "kept": hit, "words": len(text.split())})\n    for arm in ("auto", "hc"):\n        r = [x for x in rows if x["arm"] == arm]\n        k, n = sum(x["kept"] for x in r), sum(x["decisions"] for x in r)\n        w = sum(x["words"] for x in r) / max(1, len(r))\n        print(f"{arm:>4}: {k}/{n} decisions kept ({k / n:.0%}), mean summary {w:.0f} words")\n    json.dump(rows, open(E / "scores.json", "w"), indent=1)\n\n\nif __name__ == "__main__":\n    main()\n')
