BT = f'{H}/Projects/beat-tools'
s = CCSession('bt-rename', BT, '2026-08-23 22:50:13', branch='main', title='Sample pack renamer (kind_descriptor_key_bpm)')
s.user("i have ~1,900 samples across 6 packs with garbage names like `KSHMR Kick 07 (Punchy).wav`, `140_Am_dark_pluck_loop_03.wav`, `Snare - Tight 2.WAV`. write a renamer: lowercase, `<kind>_<descriptor>_<nn>[_<key>][_<bpm>].wav`, kind from a fixed list (kick snare clap hat perc bass pluck pad lead vox fx loop). dry run by default, prints old -> new. keep a csv log so i can undo")
s.bash('ls ~/Music/Samples | head; find ~/Music/Samples -iname "*.wav" | wc -l', 'Cymatics - Oracle\nKSHMR Vol 4\nLofi Keys Pack\nSplice - Trap Essentials\nUnison Drum Kit\nfree_808s\n    1894', 'Count sample files')
s.write(f'{BT}/beat_tools/rename.py', '"""Normalize sample file names: <kind>_<descriptor>_<nn>[_<key>][_<bpm>].wav (dry run unless --apply)."""\nimport argparse, csv, re\nfrom pathlib import Path\n\nKINDS = ["kick", "snare", "clap", "hat", "perc", "bass", "pluck", "pad", "lead", "vox", "fx", "loop"]\nALIAS = {"hihat": "hat", "hh": "hat", "808": "bass", "vocal": "vox", "sfx": "fx", "shaker": "perc", "rim": "perc"}\nKEY = re.compile(r"(?<![a-z])([a-g](?:#|b)?(?:m|min|maj)?)(?![a-z])", re.I)\nBPM = re.compile(r"(?<!\\d)(\\d{2,3})\\s*(?:bpm)?(?!\\d)", re.I)\nVENDOR = re.compile(r"^(kshmr|cymatics|splice|unison)\\s*(vol\\s*\\d+)?\\s*[-_ ]*", re.I)\n\n\ndef parse(stem):\n    s = VENDOR.sub("", stem.lower())\n    s = re.sub(r"[()\\[\\]]", " ", s)\n    toks = [t for t in re.split(r"[\\s_\\-]+", s) if t]\n    kind = next((ALIAS.get(t, t) for t in toks if ALIAS.get(t, t) in KINDS), "fx")\n    if "loop" in toks and kind != "loop":\n        kind = kind  # a pluck loop stays a pluck; loops are marked by bpm\n    bpm = next((int(m.group(1)) for t in toks if (m := BPM.fullmatch(t)) and 60 <= int(m.group(1)) <= 200), None)\n    key = next((t.lower().replace("min", "m") for t in toks if KEY.fullmatch(t) and t.lower() not in ("a", "b")), None)\n    num = next((int(t) for t in toks if t.isdigit() and int(t) != bpm and len(t) <= 2), 1)\n    desc = [t for t in toks if t not in KINDS and t not in ALIAS and not t.isdigit() and t not in ("loop", "bpm") and t != key]\n    return kind, "-".join(desc[:2]) or "x", num, key, bpm\n\n\ndef new_name(path):\n    kind, desc, num, key, bpm = parse(path.stem)\n    parts = [kind, desc, f"{num:02d}"] + ([key] if key else []) + ([str(bpm)] if bpm else [])\n    return "_".join(parts) + ".wav"\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("root", type=Path)\n    ap.add_argument("--apply", action="store_true")\n    ap.add_argument("--log", default="rename_log.csv")\n    a = ap.parse_args()\n    rows = []\n    for p in sorted(a.root.rglob("*")):\n        if p.suffix.lower() != ".wav":\n            continue\n        q = p.with_name(new_name(p))\n        if q.name == p.name:\n            continue\n        rows.append((str(p), str(q)))\n        print(f"{p.name}  ->  {q.name}")\n        if a.apply:\n            p.rename(q)\n    with open(a.log, "a", newline="") as f:\n        csv.writer(f).writerows(rows)\n    print(f"{len(rows)} files {\'renamed\' if a.apply else \'would be renamed (dry run)\'}")\n\n\nif __name__ == "__main__":\n    main()\n')
s.bash('uv run python -m beat_tools.rename ~/Music/Samples | tail -8', 'KSHMR Kick 07 (Punchy).wav  ->  kick_punchy_07.wav\nSnare - Tight 2.WAV  ->  snare_tight_02.wav\n140_Am_dark_pluck_loop_03.wav  ->  pluck_dark_03_am_140.wav\nOracle_Pad_Glass_C#min_90.wav  ->  pad_glass_01_c#m_90.wav\nfree 808 long G.wav  ->  bass_long_01_g.wav\nLofi Keys - Rhodes Chop 4 85bpm.wav  ->  fx_rhodes-chop_04_85.wav\nUnison_Open_HiHat_11.wav  ->  hat_open_11.wav\n1871 files would be renamed (dry run)', 'Dry-run the renamer')
s.say("Dry run renames 1,871 of 1,894 files. One miss visible in the sample: `Rhodes Chop` lands in `fx` because 'keys'/'rhodes'/'chop' aren't kinds. Want me to add `keys` as a kind (rhodes, piano, ep → keys)? Everything else in the tail looks right, including key + bpm on loops.", final=True)
s.user('yes add keys. and chop -> keep it as descriptor', gap=120)
s.edit(f'{BT}/beat_tools/rename.py', 'KINDS = ["kick", "snare", "clap", "hat", "perc", "bass", "pluck", "pad", "lead", "vox", "fx", "loop"]\nALIAS = {', 'KINDS = ["kick", "snare", "clap", "hat", "perc", "bass", "keys", "pluck", "pad", "lead", "vox", "fx", "loop"]\nALIAS = {"rhodes": "keys", "piano": "keys", "ep": "keys", ')
s.bash("uv run python -m beat_tools.rename ~/Music/Samples | grep -i rhodes | head -3", 'Lofi Keys - Rhodes Chop 4 85bpm.wav  ->  keys_chop_04_85.wav\nLofi Keys - Rhodes Chop 5 85bpm.wav  ->  keys_chop_05_85.wav\nLofi Keys - Rhodes Warm 1 70bpm.wav  ->  keys_warm_01_70.wav', 'Check Rhodes renames')
