s.user("back to the compaction experiment. hudson did blind hc marking on 8 of the 12 transcripts (experiments/hc_hudson/). rescore with an llm judge instead of keywords (claude-sonnet-5 via the anthropic sdk, key is in my env), three arms: auto, hc (me), hc (hudson). then a bar chart for the hc README")
s.read(f'{CP}/experiments/score.py', '"""Score how many hand-tagged decisions survive each compaction summary (keyword recall)."""\nimport json, re, sys, yaml\nfrom pathlib import Path\n...\ndef recovered(dec, summary):\n    s = summary.lower()\n    return all(re.search(r"\\b" + re.escape(k.lower()) + r"\\b", s) for k in dec["keys"])')
s.edit(f'{CP}/experiments/score.py', 'def recovered(dec, summary):\n    s = summary.lower()\n    return all(re.search(r"\\b" + re.escape(k.lower()) + r"\\b", s) for k in dec["keys"])', 'def recovered(dec, summary):\n    s = summary.lower()\n    return all(re.search(r"\\b" + re.escape(k.lower()) + r"\\b", s) for k in dec["keys"])\n\n\nJUDGE = """You are checking whether a decision from a coding session survived into a summary of that session.\nDecision: {d}\n\nSummary:\n{s}\n\nCould a developer who reads only the summary act on this decision correctly? Answer YES or NO."""\n\n\ndef judged(dec, summary, client, cache):\n    k = (dec["id"], hash(summary))\n    if k not in cache:\n        r = client.messages.create(model="claude-sonnet-5", max_tokens=5, messages=[{"role": "user", "content": JUDGE.format(d=dec["text"], s=summary)}])\n        cache[k] = r.content[0].text.strip().upper().startswith("YES")\n    return cache[k]')
s.edit(f'{CP}/experiments/score.py', '        for arm in ("auto", "hc"):', '        for arm in ("auto", "hc", "hc_hudson"):')
