s.say("Judge results (Sonnet as yes/no judge):\n- auto: 39/67 (58%)\n- hc (you): 57/67 (85%)\n- hc (Hudson, blind, 8 transcripts): 38/45 (84%)\n\nThe Hudson arm matters most: blind marking keeps almost the same share as yours, so the gain isn't just you knowing which decisions you tagged. On the same 8 transcripts auto keeps 26/45 (58%), so the paired gap is ~26 points. Plotting.")
s.write(f'{CP}/experiments/plot.py', 'import json\nimport matplotlib.pyplot as plt\n\nrows = json.load(open("scores.json"))\narms = ["auto", "hc", "hc_hudson"]\nlabels = ["auto compaction", "hc (author)", "hc (blind, 2nd person)"]\npct = []\nfor a in arms:\n    r = [x for x in rows if x["arm"] == a]\n    pct.append(100 * sum(x["kept"] for x in r) / sum(x["decisions"] for x in r))\nfig, ax = plt.subplots(figsize=(5, 2.6))\nax.barh(labels, pct, color=["#999999", "#4C72B0", "#55A868"])\nfor i, p in enumerate(pct):\n    ax.text(p + 1, i, f"{p:.0f}%", va="center", fontsize=9)\nax.set_xlim(0, 100); ax.set_xlabel("tagged decisions recoverable from the summary (LLM judge)")\nfig.tight_layout(); fig.savefig("../plugins/hc/docs/retention.png", dpi=200)\n')
